func run(ctx context.Context, dir, name string, args ...string) (string, error) {
	stdout, stderr, err := runWithStderr(ctx, dir, name, args...)
	if err != nil {
		msg := stderr
		if msg == "" {
			msg = err.Error()
		}
		return "", fmt.Errorf("%s %s: %s", name, strings.Join(args, " "), msg)
	}
	return stdout, nil
}

